import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"PreviewからProductionへ","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/preview-production.md","filePath":"getting-started/preview-production.md","lastUpdated":1793464466000}`),a={name:`getting-started/preview-production.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="previewからproductionへ" tabindex="-1">PreviewからProductionへ <a class="header-anchor" href="#previewからproductionへ" aria-label="Permalink to “PreviewからProductionへ”">​</a></h1><p>環境の更新は、確認用に配置して操作を確認し、許可したコミットだけを本番へ反映します。施策の「下書き→配信開始」とは別の、システム更新の手順です。</p><h2 id="previewと本番の違い" tabindex="-1">Previewと本番の違い <a class="header-anchor" href="#previewと本番の違い" aria-label="Permalink to “Previewと本番の違い”">​</a></h2><table tabindex="0"><thead><tr><th>対象</th><th>Preview</th><th>Production</th></tr></thead><tbody><tr><td>URL・パスキー</td><td>確認用の固定Origin</td><td>本番Origin</td></tr><tr><td>DB・ユーザー・施策</td><td>確認用D1</td><td>本番D1</td></tr><tr><td>Durable Objects</td><td>Preview専用</td><td>本番専用</td></tr><tr><td>Access</td><td>許可された担当者に限定</td><td>運用方針に従う</td></tr><tr><td>Jev</td><td>初期構成は固定スタブ</td><td>本番キーで実判定</td></tr></tbody></table><p>CloudflareのWorker Previewsを使います。Version URLは本番リソースを共有するため、この分離確認の代わりには使いません。</p><h2 id="_1-確認版を作る" tabindex="-1">1. 確認版を作る <a class="header-anchor" href="#_1-確認版を作る" aria-label="Permalink to “1. 確認版を作る”">​</a></h2><p>設定・実装をコミットし、テストを通します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:cloudflare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:preview</span></span></code></pre></div><p>スクリプトが本番と異なるDB、移行先、制限用namespace、認証設定を検証します。Previewだけへ移行と配備を行い、<code>data/deployments/preview.json</code>にコミットとDeployment IDを保存します。</p><p>固定のPreview URLを使ってください。個別Deployment URLはパスキーの登録先として使いません。</p><h2 id="_2-確認する" tabindex="-1">2. 確認する <a class="header-anchor" href="#_2-確認する" aria-label="Permalink to “2. 確認する”">​</a></h2><ul><li>Accessで入場し、パスキーの登録・再ログインを確認する。</li><li>対象サイトを切り替え、権限を確認する。</li><li>施策の下書き保存・配信開始・停止を確認する。</li><li>同一Originのデモページで表示と共通デザインを確認する。</li><li>画面上部の確認版コミットを控える。</li></ul><p>スタブの0.95をJevの実測や施策効果として扱いません。実モデルの確認は別途キーと費用枠を設定したうえで行います。</p><p>Accessで全体を保護したAPIへ、外部サイトのSDKから認証Cookieなしで通信することはできません。現在の非公開Previewでは同一Originのデモを使います。外部サイトとの試験には、管理画面と配信APIの保護範囲を別途設計します。</p><h2 id="_3-許可した版を本番へ反映する" tabindex="-1">3. 許可した版を本番へ反映する <a class="header-anchor" href="#_3-許可した版を本番へ反映する" aria-label="Permalink to “3. 許可した版を本番へ反映する”">​</a></h2><p><strong>確認が終わり、本番反映が明示的に許可された後</strong>に実行します。</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reviewed-commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FULL_40_CHARACTER_COMMIT_SHA</span></span></code></pre></div><p>HEAD・作業ツリー・配備記録・Production設定のハッシュを照合し、未確認や未コミットの変更があれば停止します。短い7文字のSHAではなく40文字のSHAを指定します。</p><p>確認用のDB、アカウント、パスキー、施策を本番へコピーしません。本番側は本番データを使い、本番Originで初回登録します。</p><h2 id="更新時の注意" tabindex="-1">更新時の注意 <a class="header-anchor" href="#更新時の注意" aria-label="Permalink to “更新時の注意”">​</a></h2><p>このリポジトリのCIは検査だけを行います。<code>cf:deploy</code>も同じ確認を要求し、配備記録なしでは停止します。Cloudflare Buildsや別の外部CIに直接<code>wrangler deploy</code>を設定している場合はこの確認を通らないため、自動の本番配備を無効にして手動リリースへ統一してください。外部サービスの連携設定は、コードの変更だけで自動的に解除されません。</p><p>配備記録がない新しい作業環境では、同じコミットをPreviewへ再配置して記録と確認を作り直します。複数ブランチを同時に試す場合はPreview名・D1・Origin・移行設定をそれぞれ分けてください。</p><p>本番のバックアップと切り戻しは<a href="./../operations/maintenance">更新・復旧</a>を参照してください。</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};